ROOT=Path(__file__).resolve().parents[1];out=[]
def card(ch,title,summary,formula,method,example,answer,pitfalls,pages,learn,exam):
 n=1+sum(x['chapter']==ch for x in out)
 out.append(dict(id=f'r{ch}-{n}',chapter=ch,title=title,summary=summary,formula=formula,method=method.split('|'),example=example,answer=answer,checks=pitfalls.split('|'),pages=pages,learn=learn,sourcePages=exam))
card(1,'精确频度的四类边界','先写计数式，再化简阶数。不能用一个 O(n²) 代替题目要求的精确次数。','Σi=n(n+1)/2；ΣΣj=n²(n+1)/2；从1起、上界n≥1、每次乘整数b>1：⌊log_b n⌋+1','固定外层变量，逐一写内层执行次数|注意 < 和 <=，首值与尾值是否真的执行|相关循环求和，几何增长取对数；最后才取主导项','i=1; while(i<=64){ @; i*=2; }。另求 i=1..6,j=1..i 的 @ 次数。','i 取 1,2,4,8,16,32,64，共 7 次，不是 6。三角循环为 1+2+3+4+5+6=21 次。两者分别 O(log n)、O(n²)。','把退出检查误算成一次 @|把相邻两个循环误当嵌套|只写大 O 丢掉精确频度分','41–54、61–68','1-6',[3,14,21,31])
card(1,'算法性质、数据与评价','客观题要区分“算法的特征”“设计要求”“结构的要素”。','特征：有穷、确定、可行、零个或多个输入、至少一个输出；结构：逻辑、存储、运算','识别问的是哪一组概念|区分数据元素与元素内部的数据项|性能问题先明确输入规模与所计操作','题目说异常输入时能正确处理，属于哪项要求？频度 10¹⁰n³+n⁴ 的阶数呢？','异常处理对应健壮性；主导项是 n⁴，即使常数 10¹⁰ 很大也不改变渐近阶数。','输入不是至少一个|可读性不是算法五特征|平均情况没有概率分布就不完整','13–40、55–58','1-1',[1,12,28])
card(1,'从递推到空间','把总操作数、递归深度和同时存活的空间分开计算。','阶乘：T(n)=T(n−1)+O(1)；汉诺塔：T(n)=2T(n−1)+1','按基本算术常数耗时、每帧常数空间的课程模型分析|递归画最深调用链估算栈空间|把每层处理量求和估计时间|若有多个不同时存活的临时数组，按峰值而非机械累加','n 层阶乘和 n 盘汉诺塔的总时间与额外栈空间分别是什么？','阶乘时间 O(n)、栈 O(n)；汉诺塔时间 O(2ⁿ)、栈 O(n)。总调用数很大不等于同时保留指数个栈帧。','遗漏调用栈|把时间和空间直接写成同一个阶|混淆峰值与累计分配量','39、53–54','1-6',[3,14,31])
card(2,'有序循环链表插入','编码题要先写清有无头结点，以及循环尾部回到哪里。','带头循环：空表 L->next=L；循环边界 p->next!=L；先 s->next 再 p->next','固定 p 指向插入位置前驱，从 L 开始|while(p->next!=L && p->next->data<=x) p=p->next|分配新结点，先接原后继再把前驱指向它；空表、首插、尾插统一处理','L→3→7→11→L，插入 1；再考虑空表插入 5。','查找从头结点开始，3>1 故停在 L：让 s.next 指向值为3的原首元，再 L.next=s。空表时先让 s.next=L，再 L.next=s，仍形成环。','用 NULL 判断循环链表结束|先修改前驱链接导致丢失后继|漏空表或把头结点值参与比较','33–38、46–49','2-4',[3,25])
card(2,'删值、逆置与双向修复','得分关键是“不漏元素、不丢链、不访问已释放空间”。','删值命中后 pre 不移动；逆置前保存 q=p->next；双向删除改两条邻居链接','删除所有重复值：pre 固定，p=pre->next 重新检查新后继|逆置用头插法：先保存原后继，再插入新表头|双向删除先改 prior->next 与 next->prior，最后释放','L→2→2→3→2，删除所有 2。为什么命中后不能同时 pre=p,p=p->next？','删第一个 2 后 pre 仍为 L，检查新的首元 2，最终得到 L→3。若先释放 p 后再读 p->next 就是释放后访问；若无条件前移会漏连续命中。','连续命中漏删|释放后仍读取 p 的域|逆置未保存 q|无头链删除首元未更新调用者头指针','39–45、50–52','2-4',[14,29,30])
card(2,'顺序表位序与移动计数','“第 i 个”从 1 起，“数组下标”从 0 起。插入与删除的长度基准不同。','插入移动 n−i+1；删除移动 n−i；地址 base+(i−1)L','确认位序合法范围：插入 1..n+1，删除 1..n|把需要移动的原下标逐个列出|插入从后往前搬，删除从前往后补','长度 12，第 8 位插入；随后删除新插入项，两个操作各移动多少？','插入原第 8..12 位，共 5 个；插入后长 13，删第 8 位移动 13−8=5。不要把删除仍按旧长度 12 计算。','n 与容量混用|n−i 与 n−i+1 差一|已知结点 O(1) 误扩展为按值定位也 O(1)','9–20、53–55','2-2',[1,11,25])
card(3,'出栈合法性与最小容量','只要输出不可能，就不应继续计算一个“最小容量”。','模拟 push 到目标出现，再要求栈顶值=目标；容量=模拟栈长峰值','用入栈下一个编号 next 和显式栈记录状态|目标尚未入栈就顺序压入；已经入栈却不在顶则失败|合法序列记录最大同时在栈元素数；队列不会再次改变次序','1..6 入栈，经弹出进入 FIFO 队列，要求输出 2,4,3,6,5,1。','压 1,2 后弹 2；压 3,4 后弹 4,3；压 5,6 后弹 6,5，再弹 1。峰值 3，因此最小容量 3。','把一次性全压入当成唯一方法|只检查输入输出元素集合|忘记前面没弹出的元素还在栈底','1–9','3-1',[2,12,19,26])
card(3,'表达式：顺序比算术更容易失分','后缀题重点是每次弹出的左右操作数，以及中缀的结合性。','二元运算：b=pop,a=pop,push(a op b)；左结合等优先级先弹栈顶','转换先保留操作数原顺序|遇右括号一直弹到左括号，括号本身不输出|计算时用栈逐项列状态，不交换减除左右操作数','后缀 5 3 - 2 * 18 6 / +；中缀 a-b/c+d。','后缀前段 (5−3)×2=4，后段 18/6=3，总和 7。转换结果 a b c / - d +。','18/6 误算 6/18|把 (a−b)/c 代入 a−b/c|除法结合方向看错','13–19','3-3',[1,11,23])
card(3,'循环队列与链队删空','先固定 front/rear 语义和空满方案，再套公式。','保留一空位：len=(rear−front+m)%m；满 (rear+1)%m=front','题干若是保留一个空位，有效容量 m−1|出队只推进 front，入队只推进 rear，各自取模|无头链队删空时两指针为NULL；带头链队删空时rear回到头结点','m=8，front=6,rear=2，出队 2 次再入队 1 次。','初长=(2−6+8)%8=4；front=(6+2)%8=0，rear=(2+1)%8=3，终长 3。','把计数方案和牺牲一单元方案混用|对 p 而非队列容量 m 取模|无头链队只清 front 留悬空 rear','26–37','3-5',[25,26,27])
card(3,'递归与受限双端队列','递归题看“执行次数”，双端队列题看“哪端允许哪种操作”。','汉诺塔 2ⁿ−1 次；递归深度 n；输入受限=一端插入、两端可删','递归先写基例，明确是否计 n=0 空调用|计算总次数和深度要用两个表达式|先画允许输入/输出的端，再判断受限类型','7 个盘的汉诺塔；以及只允许右端入、两端出的队列。','最少 127 次移动，非空调用最大深度 7；第二个结构是输入受限双端队列。','总调用与峰值深度混淆|输入受限与输出受限名称记反','20–25、35–36','3-4',[21,26])
card(4,'二维映射与反求维度','先换算元素偏移，再换算字节；遇到地址差可以倒推列数。','行优先 offset=(i-r₀)n+(j-c₀)；列优先 offset=(j-c₀)m+(i-r₀)','数清行列长度=上界−下界+1|基址必须对应下界元素|地址差先除 L，然后解维度或下标，最后代回校验','A 从 [0][0] 起按行存，每元素 1 字节，base=644，a[2][2]=676，求列数和 a[4][5] 地址。','676−644=32=2n+2，所以 n=15；a[4][5]=644+4×15+5=709。','忘记上下界不是 1|把元素偏移当字节差|列优先错误地仍乘列数','4–9','4-1',[22,24,25])
card(4,'压缩矩阵：区分零与对称','对称矩阵上三角要映射，下三角矩阵的上三角才是零。','下三角存 n(n+1)/2；k=i(i−1)/2+j−1（原坐标1起、B下标0起）；三对角 3n−2','先确定特殊矩阵类型|确定 B 从 0 还是 1 起，区分位置与地址|对称上三角先交换 i,j，再套下三角公式','对称矩阵只存下三角，问 a[2][5] 的 0 起始压缩下标。','改查 a[5][2]，k=5×4/2+2−1=11；若 B 从 1 起，位置为 12。','把上三角都答为 0|压缩数组与原矩阵坐标混用|三对角地址漏乘元素大小','10–14','4-3',[11,22])
card(4,'三元组、快速转置与行链表','题目会要求从矩阵跨到三元组、链表或图表示，不能只会一个地址公式。','快速转置 O(列数+非零元数)；cpot[1]=1；cpot[c]=cpot[c−1]+num[c−1]','按行序列出非零三元组，保留矩阵维度元数据|转置交换行列后恢复新行序；快转置先统计列计数|行链表只在该行连接，十字链表同时维护行、列链接','num=[2,0,3,1]，未填入前 cpot 是什么？','cpot=[1,3,3,6]。零元素的列没有占位段，所以后一列可以共享起始位置。填入时 cpot 会递增，不再保持原起点。','把所有零元也存成三元组|只交换下标不重排|把 cpot 填写后的末位置当初始起点','15–28','4-5',[2,12,45,46])
card(5,'二叉树数量、形状与完全性','任意二叉树和完全二叉树的计数式不能混套。','任意非空 n₀=n₂+1；完全树叶子 ⌈n/2⌉；h=⌊log₂n⌋+1；互异标识固定先序的形状数 Cₙ=binom(2n,n)/(n+1)','先识别题干是否保证完全|用 n=n₀+n₁+n₂ 联立度数性质|先序固定仍可有不同左右形状；Cₙ 是卡特兰数，计 n 个结点、区分左右的二叉树形状|n=3 时可按左子树有0、1、2个结点分成2、1、2种，共5种','任意二叉树 n=2014、n₁=13，求叶子；若另是一棵 n=2013 的完全二叉树呢？','任意树 n₀=(2014−13+1)/2=1001；完全树叶子=⌈2013/2⌉=1007。两题前提不同。','任意树直接套 ceil(n/2)|层数从0/1起混用|固定前序误以为唯一树','9–17','5-2',[1,11,21,24])
card(5,'遍历重建：树、遍历、顺序编号','8 分综合题常把树形、另一种遍历和顺序存储捆在一起。','先序首元素为根；后序末元素为根；中序切左右；位置号：左2i、右2i+1','先确认结点标识互异，再标出当前根在中序的位置|按中序左段长度切分另一遍历，递归构树|最后才做另一遍历和完全树位置编号，空位不挤掉','先序 ABDEC，中序 DBEAC。求后序和最大顺序位置编号。','根 A；左子树 B，其左右为 D、E；右子树 C。后序 DEBCA。位置 A1,B2,C3,D4,E5，最大编号5。','把后序最后一个当左根|左右子序列长度切错|顺序编号把缺位压缩掉','20–24','5-4',[4,13])
card(5,'由指针表还原逻辑结构','表中的物理编号只是地址标签；必须从 T 根指针走链接。','按 Lchild/Rchild 访问；非空二叉树 n 个结点共有 n+1 个空孩子指针域','先抄出编号→值映射|从 T 开始画左右链接，记录访问过的编号|求遍历按值输出，顺序存储另算位置号','T=3；(编号,值,左,右)：(1,B,0,0),(2,C,0,0),(3,A,1,2)。','逻辑根是值 A，左 B 右 C；前 ABC、中 BAC、后 BCA。根不在物理编号1不影响结构。','按表列序直接写遍历|把编号当数据域|把指针表编号当完全树位置编号','15–24','5-3',[10,34,35,36])
card(5,'二叉表示还原树与森林','左孩子是第一孩子，右孩子是下一兄弟；根的右链决定森林根。','一般树孩子链 = left 后连续 right；森林根链 = root 后连续 right','先沿根右链列出森林各树的根|对每个结点，从其左孩子开始沿右链列全部孩子|还原后重新检查双亲是否唯一、结点有无重复','A.left=B,A.right=D；B.left=C,B.right=E；D.left=F。','森林根为 A、D；A 的孩子是 B、E，B 的孩子 C；D 的孩子 F。E 不是 B 的孩子，它是 B 的兄弟。','把二叉右孩子直接当原树孩子|漏掉第二棵树根|把兄弟链重复挂到多个父结点','25–39','5-5',[10,28,35,36])
card(5,'哈夫曼构树与可接受编码','参考图可以不同，评分应看每步最小合并、前缀性与最优 WPL。','WPL=Σwᵢlᵢ=合并新权值之和；wᵢ 为叶子权，lᵢ 为码长；n叶子→2n−1个结点（n≥2）','每步重排当前权值集合，取最小两项合并|树边左0右1后从根读叶子码|用叶子权×路径边数与合并代价和交叉检查','权值 2,4,5,9，构树与 WPL。','2+4=6，5+6=11，9+11=20；WPL=6+11+20=37。编码可以因左右或等权次序变化，但成本不变。','合并原始最小两项后不放回新根|把根层1当码长1|照抄手写某组码而忽略另一组合法码','40–44','5-7',[9,17,43,44])
card(5,'平均码长与压缩比','WPL、平均码长、固定长位数与压缩比是四个不同的量。','平均码长=WPL/Σ权；N≥2 时固定长位数=⌈log₂字符数⌉（字符数记为 N）；压缩比按题干定义','先判断给的是频数还是概率|平均码长除总频数；概率和1时 WPL 就是平均码长|写清压缩比是原/新还是新/原，并说明是否忽略码表','频数 35,25,20,10,6,4，最优 WPL=230，求平均码长与“原固定长/哈夫曼”比值。','总频数100，平均2.3位；6个字符固定长3位；比值3/2.3=30/23≈1.30435。','把非归一权值的 WPL 当平均码长|log₂6 不向上取整|把节约百分数当压缩比','45–47','5-8',[9,17,43,44])
card(5,'BST 形状赋值与中序约束','给定形状填 1..n，就按中序依次赋递增值；不是按层填。','互异键的 BST 中序递增；等概率成功 ASL=Σ结点层数/n','先写形状的中序结点位置|将排序后的关键字逐一对应位置|查找比较次数等于目标层数，根计1','根有左、右叶子三个位置，把 1,2,3 填成 BST，并求成功 ASL。','中序位置为 左、根、右，因此左1、根2、右3；层数和1+2+2=5，ASL=5/3。','按层填成根1|只检查直接孩子却忽略整棵子树范围|ASL 分母误用边数','48–53','5-6',[8,33,40])
card(6,'矩阵、三元组与邻接表互转','图形综合题常先转存储结构，再做遍历。','无向图邻接矩阵对称；有向表每弧一个边结点，无向通常两个','确认是有向还是无向、0是否表示无边|每行邻接矩阵对应该顶点的出邻居|按题设邻接次序排列，后续遍历复用同一规则','有向边 (1,2,3),(1,5,6),(2,1,4),(2,3,5)。','1 的邻接表是 (2,3),(5,6)；2 的是 (1,4),(3,5)。不自动添加反向弧，权值字段要保留。','把有向图也做成对称|漏权值或漏孤立顶点的空表|矩阵的行与列方向看反','13–18','6-2',[5,16,45,46])
card(6,'DFS/BFS 的确定次序','遍历结果随邻接次序变化；题库统一明确升序，避免“图画位置”决定答案。','DFS 用递归/栈；BFS 用 FIFO，入队即标记；邻接表 O(V+E)','从指定起点开始，按题设顺序取未访问邻居|DFS 走深并回退，BFS 一层层出队|只要求可达部分就不额外启动；全图遍历须继续未访问点','无向边 1-2,1-3,2-4,2-5,3-5,5-6，升序邻居，从1出发。','DFS 1,2,4,5,3,6；BFS 1,2,3,4,5,6。','BFS 出队才标记导致重复入队|DFS 回退时又重复输出|漏有向边方向|未说明邻接次序就声称只有一种答案','19–27','6-3',[5,16,20,47])
card(6,'拓扑排序：队列、栈和多解','若题设指定栈或队列，必须遵守取出顺序；只问合法序列时可有多解。','每条弧 u→v 要满足 pos(u)<pos(v)；输出数<V 表示有环','先列入度，选择零入度点|输出后只删除它的出边，相应目标入度减一|按指定容器加入新的零入度点，并统计输出总数','弧 1→3,2→3,2→4,3→5,4→5,5→6，初始零入度升序入 FIFO。','初队列1,2；先出1，再出2并入3,4，之后3,4,5,6。结果1,2,3,4,5,6。','“有多个零入度点”误判为有环|把未指定的栈次序当唯一答案|只删顶点不更新入度','43–48','6-6',[12,20,27])
card(6,'AOE 全表：ve 与 vl','最长依赖链决定最短总工期，是综合题的主要过程分。','ve[v]=max(ve[u]+w)；vl[u]=min(vl[v]−w)；终点 vl=ve','本专题为单源单汇DAG，活动可按依赖并行，不另计资源争用|ve 是事件最早时间，vl 是不推迟工期的最晚时间；源事件 ve 设0|按拓扑序用 max 求 ve，工期取汇点 ve；汇点 vl=ve，再逆拓扑用 min 求 vl|中间步骤列成表，检查每个 ve<=vl','1→2=3,1→3=2,2→4=5,3→4=4,4→5=2。','ve=[0,3,2,8,10]；vl=[0,3,4,8,10]。工期10，3有2个单位松弛。最早取max，因为要等所有前驱。','把 ve 误求成最短路 min|反向求 vl 仍用 max|用相邻点编号代替拓扑序|工期取所有活动之和','49–60','6-7',[7,18,49,50,51,52])
card(6,'关键活动、松弛与多条关键路径','活动不是事件，活动 e/l 要用弧两端事件的不同量。','活动 u→v：e=ve[u]，l=vl[v]−w；w 为活动工期；余量=l−e；关键当且仅当 e=l','e、l 分别是活动最早、最晚开始时间，区别于事件 ve、vl|先完成事件 ve/vl 表，避免活动公式混入递推|按题给活动顺序逐条算 e,l,余量|标全部零余量活动，再按可连接的源汇路径识别关键路径','已知活动3→4持续4个时间单位，且 ve[3]=2、vl[4]=8。求它是否关键。','e=2，l=8−4=4，余量2，因此不关键；即使终点4在关键路径上，该活动仍可能不关键。','把 e 写成 ve[v]|忘记 l 中减活动工期|零余量活动只找出一条|存在多条关键路径时只缩一条就说工期必减','49–60','6-7',[7,18,49,50,52])
card(6,'Dijkstra 的松弛表与路径回溯','写最终距离之外，还要能说明每轮确定和前驱更新。','dist[v]=min(dist[v],dist[u]+w)；边权需非负','起点0、其余∞；每轮选未确定最小dist|确定后松弛它的出边，改善时同步更新前驱|按前驱从目标倒推回源点，再反转得到路径','1→2=6,1→3=2,3→2=1,2→4=2,3→4=8,4→5=3。','最终 dist=[0,3,2,5,8]，确定序1,3,2,4,5；到5路径1,3,2,4,5。从3更新2，再经2改善4。','把边最小当 dist 最小|图有向却沿反边走|负权仍无条件使用|dist 改了但前驱没改','39–42','6-5',[47,48])
card(6,'生成树与图边界：课件补全','资料中的遍历、AOE优先，但课件中的 MST、度数和复杂度也要覆盖。','无向 Σdegree=2E；生成树E=V−1；Prim O(V²)，Kruskal O(E log E)','MST先确认连通无向带权条件|Prim选跨当前集合边界的最小边，Kruskal按权避环|区别整树权和最小与源点到各点距离最小','三角图1-2=2,1-3=5,2-3=1。求MST。','选2-3和1-2，总权3；用2条边连通3点且无环。此处为课程范围补全，不能据此把 MST 声称为资料高频。','MST和最短路径树混用|把单向可达当强连通|用邻接表遍历复杂度套矩阵','1–12、28–38','6-4',[2,24,28])
card(7,'折半路径、判定树与 ASL','成功、失败、向上/向下取中点，都可能改变具体比较路径。','等概率成功 ASL=Σ层数/n；闭区间 low<=high；成功最大比较 ⌊log₂n⌋+1','先写 low/high 与取中点规则|每比较一次记目标关键字而非空区间判断|ASL 可按判定树逐层计数，n不足满层时单独算','有序1..16，mid向下取整，成功ASL多少？','各层个数1,2,4,8,1，比较次数和1+4+12+32+5=54，ASL=54/16=3.375。最多5次；失败也不能把空区间检查计成关键字比较。','low<high漏最后候选|n=16误当4层满树|ASL总是写log₂n|失败与成功计数混在一起','1–11','7-2',[1,11,22,23,37,38])
card(7,'BST 构造、删根与成功 ASL','树形由插入次序决定，删除两孩子结点需指定前驱或后继。','根计第1层，查找代价=层数；后继=右子树最左结点；等概率成功 ASL=层数和/n','按输入次序从根比较插入，保持全子树范围|删除先分类0、1、2孩子，两孩子再删替代值原结点|ASL逐点累加层数，根算1，不只计边','插入20,10,30,5,15,25,35后删20，统一用后继。','用25替换根20，再删原右子树中的25叶子；新根25，左子树10带5,15，右子树30仅右35。','用后继替代后未删原后继|把左子树所有值限制忘掉|按排序后序列重建而不是给定输入序','17–19','7-4',[8,33,40])
card(7,'AVL 的四种旋转','先找最近失衡祖先，再看插入路径的两段方向。','BF=左高−右高；LL右旋、RR左旋、LR先左后右、RL先右后左','自下向上检查|以失衡祖先为起点描述两段路径|旋转后检查中序保持、所有子树链接和高度','依次插30,10,20，属于何型？','失衡点30，路径左再右，LR；先对10左旋，再对30右旋，得到根20、左10、右30，中序10,20,30。','把LL当左旋|只改三个数而丢中间子树|用右高−左高却套左高−右高符号','20–27','7-5',[1,11])
card(7,'哈希构造、模数与成功 ASL','题干中的 p 与表长 m 可不同，成功次数含最终命中槽。','H=key%p；探测 pos=(H+j)%m；α=n/m；等概率成功ASL=Σ探测次数/n','先由装填因子按题设确定整数表长|逐键写初地址和探测链，超过末尾对 m 绕回|空槽不参与成功ASL分母，命中槽要算一次','m=8,H=key%7，依次插32,13,49,55,22,39,20。','表0..7=[49,22,20,空,32,39,13,55]；按插入次序次数[1,1,1,2,1,2,5]，成功ASL=13/7。','探测错误地对p取模|把α取整而没按题意解释|碰撞后只加一次|遗漏最后命中那次比较','28–38','7-7',[10,13,41,42])
card(7,'失败 ASL、删除标记与分块边界','复习时要把“平均的样本空间”明确写出来。','失败从初地址到第一个普通空槽；初址概率以题设为准；分块先定位范围再块内顺扫','若 H=key%p 且非负 key，可能初址只有0到p−1，不能自动把m个槽都当初址|先按题设列每个可能初地址的失败探测次数|空槽这次是否计数，以题设为准|开放定址删除不应直接截断探测链；分块要求块间整体有序','m=7，键1,8,15线性探测放在1,2,3。失败查找从地址1开始要检查几次？','检查1、2、3后再检查空槽4，共4次。失败ASL不是把已有三个键的成功次数平均；删除地址2也不能直接当普通空槽而漏掉15。','成功ASL除m|失败ASL未看初地址概率就机械除m或n|忽略空槽检查|只让索引最大值递增却允许块范围交叠','12–16、34–38','7-3',[12,13,41,42])
card(8,'快排：指定实现下的每次划分','同一基准也可以有不同合法中间排列，考试先读实现约定。','首元素挖坑法：右扫>=pivot，左扫<=pivot，相遇回填；两侧分别递归','暂存基准，先右后左扫描|每次填坑后另一侧形成新坑，不丢重复值|写当前区间与基准最终位置，再按规定递归顺序写下一次','[47,79,56,38,40,84] 做一次首元素挖坑划分。','结果[40,38,47,56,79,84]，基准47归位到0起始下标2；左段[40,38]尚未有序。','把一次划分直接写成最终排序|不说明实现却套另一种标准答案|重复值扫描条件产生死循环','27–29','8-7',[6,23,39])
card(8,'希尔：按间隔分组的逐趟结果','一趟指一个增量完成后的整个数组，不能只写各组局部结果。','同组下标模 gap 相同；最终 gap 必须为1；复杂度依增量','先把每组的下标列出|每组插入后仍放回原间隔位置|等全部组完成再抄一整行，缩小增量继续','[10,18,4,13,16,5,10,8,2]，增量5,3,1。','gap5后[5,10,4,2,16,10,18,8,13]；gap3后[2,8,4,5,10,10,18,16,13]；gap1后[2,4,5,8,10,10,13,16,18]。','分成连续前后块|还没做完所有组就抄趟结果|把复杂度统一写成nlogn','7–10','8-3',[6,39])
card(8,'堆：建堆与缩小边界','区分初始建堆、取顶交换和恢复剩余堆三步。','0起始：左2i+1、右2i+2；最后非叶 ⌊n/2⌋−1；大根堆升序','从最后非叶向根筛选建堆|交换堆顶到堆尾，先缩小堆大小|只对剩余堆筛选，有序后缀不能重新参与','[4,1,3,2] 建大根堆，再取出最大值一趟。','建堆[4,2,3,1]；交换4到末尾再调整前三项，得到[3,2,1,4]，堆大小3。','直接排序后当成建堆结果|把已输出后缀又调回堆|把堆的父子关系当BST左右全局范围','15–22','8-5',[15,19])
card(8,'冒泡、插入、选择：过程和精确次数','识别算法依据每趟不变式，计算比较与移动先固定提前退出规则。','选择比较n(n−1)/2；交换通常按3次记录移动；插入有序前缀每趟+1','冒泡每趟把最大值沉到右界|选择每趟从全无序区找最小交换到前端|插入暂存当前值，向右移动严格较大值；分别统计比较与移动','[3,1,4,2,5] 做有 changed 的冒泡，共几次比较与交换？','逐趟比较4、3、2次，交换2、1、0次，最后无交换退出；共9比较、3交换、9记录移动。','用固定n(n−1)/2代替提前退出后的实际比较|把交换与移动等同|插入第i趟有序区长度差一','3–6、11–14、23–26','8-6',[12,32,40])
card(8,'稳定性、最坏界与选型','要能给反例，不只背一个“稳定/不稳定”表。','稳定：直接插入、相等放后方的折半插入、严格逆序才交换的冒泡；通常不稳：选择、希尔、堆、快排','相等键加甲乙身份，看是否可能颠倒|复杂度同时写输入状态和实现前提|有最坏界+空间限制的选型要逐项排除','[2甲,2乙,1] 做选择第一趟后怎样？若要求最坏nlogn且迭代空间常数，选什么？','第一趟交换成[1,2乙,2甲]，证明可不稳定；选堆排序。普通快排最坏n²，且有递归栈。','以某一次未破坏次序证明稳定|把课件末页折半插入不稳定照抄|把快排平均界当最坏保证','1–2、30–32','8-1',[6,12,15,39])
from refine_curriculum import FORMULAS, NOTATION
for item in out:
 item['formula']=FORMULAS.get(item['id'],item['formula'])
 item['notation']=NOTATION[item['id']]
 if item['id']=='r5-1':item['method']=['先看题目保证任意、完全还是满，不能跨前提套公式。','任意非空树用结点数、边数两种计数联立；完全树按层靠左填。','只给先序不唯一；3个结点按左子树规模0、1、2分类，形状数为2+1+2=5。']
 if item['id']=='r7-5':
  item['title']='分块查找与补充边界'
  item['sourcePages']=[]
(ROOT/'review-lessons.js').write_text('window.REVIEW_LESSONS = '+json.dumps(out,ensure_ascii=False,indent=2)+';\n')
print('Independent exam review modules',len(out))
